import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BPKcPtvA.js";const h=JSON.parse('{"title":"First login","description":"Create your admin account and configure GateKeeper for the first time.","frontmatter":{"title":"First login","description":"Create your admin account and configure GateKeeper for the first time."},"headers":[],"relativePath":"getting-started/first-login.md","filePath":"getting-started/first-login.md"}'),i={name:"getting-started/first-login.md"};function n(s,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="step-1-visit-the-admin-panel" tabindex="-1">Step 1 - visit the admin panel <a class="header-anchor" href="#step-1-visit-the-admin-panel" aria-label="Permalink to &quot;Step 1 - visit the admin panel&quot;">​</a></h2><p>After starting GateKeeper for the first time, go to <code>/admin</code> in your browser. Since no admin account exists yet, GateKeeper redirects you to <code>/admin/setup</code>.</p><h2 id="step-2-create-your-admin-account" tabindex="-1">Step 2 - create your admin account <a class="header-anchor" href="#step-2-create-your-admin-account" aria-label="Permalink to &quot;Step 2 - create your admin account&quot;">​</a></h2><p>Enter your email address and a password (minimum 12 characters). Click <strong>Create admin account</strong>.</p><p>This page only appears once. Once an admin account exists, the setup page redirects to the normal login and cannot be accessed again.</p><h2 id="step-3-configure-smtp" tabindex="-1">Step 3 - configure SMTP <a class="header-anchor" href="#step-3-configure-smtp" aria-label="Permalink to &quot;Step 3 - configure SMTP&quot;">​</a></h2><p>Without SMTP, GateKeeper cannot send one-time login codes or password reset emails.</p><p>Go to <code>/admin/settings</code> and fill in your SMTP details, then click <strong>Save changes</strong>. The change takes effect immediately - no restart needed.</p><h2 id="step-4-secure-your-admin-account" tabindex="-1">Step 4 - secure your admin account <a class="header-anchor" href="#step-4-secure-your-admin-account" aria-label="Permalink to &quot;Step 4 - secure your admin account&quot;">​</a></h2><p>Go to <code>/admin/profile</code> and:</p><ul><li>Enroll an <strong>authenticator app</strong> (TOTP) for a second factor on admin login</li><li>Register a <strong>passkey</strong> if your device supports it (Touch ID, Face ID, or a hardware key)</li></ul><h2 id="step-5-create-users" tabindex="-1">Step 5 - create users <a class="header-anchor" href="#step-5-create-users" aria-label="Permalink to &quot;Step 5 - create users&quot;">​</a></h2><p>Go to <code>/admin/users</code> and click <strong>New user</strong>. Choose:</p><ul><li><strong>Email + Password</strong> - standard account with a temporary password. The user is required to change it on first login.</li><li><strong>Email Only</strong> - passwordless account. The user signs in with just their email and a one-time code sent to it.</li></ul><h2 id="step-6-test-the-login-flow" tabindex="-1">Step 6 - test the login flow <a class="header-anchor" href="#step-6-test-the-login-flow" aria-label="Permalink to &quot;Step 6 - test the login flow&quot;">​</a></h2><p>Open a private browser window and go to <code>https://auth.example.com/login</code>. Sign in with the user credentials you created and verify the full flow works.</p><h2 id="step-7-protect-your-apps" tabindex="-1">Step 7 - protect your apps <a class="header-anchor" href="#step-7-protect-your-apps" aria-label="Permalink to &quot;Step 7 - protect your apps&quot;">​</a></h2><ul><li><strong>ForwardAuth</strong> - add the GateKeeper middleware to Traefik to protect any service. See <a href="/integrations/traefik-forwardauth.html">ForwardAuth setup</a>.</li><li><strong>OIDC</strong> - register an OIDC client to let apps like Grafana, Jellyfin, or Traefik Manager use GateKeeper as an identity provider. See <a href="/admin/managing-clients.html">Managing OIDC clients</a>.</li></ul><h2 id="navigation-shortcuts" tabindex="-1">Navigation shortcuts <a class="header-anchor" href="#navigation-shortcuts" aria-label="Permalink to &quot;Navigation shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>⌘K</code> / <code>Ctrl+K</code></td><td>Command palette - search users, clients, navigate</td></tr><tr><td><code>g d</code></td><td>Dashboard</td></tr><tr><td><code>g u</code></td><td>Users</td></tr><tr><td><code>g c</code></td><td>OIDC Clients</td></tr><tr><td><code>g a</code></td><td>Audit log</td></tr><tr><td><code>g s</code></td><td>Settings</td></tr></tbody></table>',20)])])}const g=t(i,[["render",n]]);export{h as __pageData,g as default};
